use js_runtime::{Runtime,Value};
fn mem(){let text=std::fs::read_to_string("/proc/self/status").unwrap();for line in text.lines().filter(|line|line.starts_with("VmRSS:")||line.starts_with("VmHWM:")){eprintln!("{line}")}}
fn main(){let start=std::time::Instant::now();let bytes=std::fs::read("work/native-oracle-warm23-current.js.tables.json").unwrap();let text=String::from_utf8(bytes).unwrap();let mut rt=Runtime::new();let input=rt.string(&text);eprintln!("input_ready_ms:{}",start.elapsed().as_millis());mem();let parse=std::time::Instant::now();let output=rt.json_parse(input,Value::Undefined).unwrap();let key=rt.string("tables");let tables=rt.get(output,key).unwrap();let table_count=rt.own_keys(tables,true).unwrap().len();eprintln!("parse_ms:{} objects:{} tables:{}",parse.elapsed().as_millis(),rt.objects.len(),table_count);mem();}
